/**
 * Environment contract of pages-service.
 *
 * Binding types are generated by `wrangler types` into `worker-configuration.d.ts`,
 * while this interface describes what the service expects to receive: if config
 * and interface diverge, compilation fails rather than runtime.
 *
 * The service owns its own database (database-per-service) and is not exposed
 * outward: only the gateway is public, inside there is only a Service Binding.
 */
export interface Bindings {
  DB: D1Database;
  ENVIRONMENT: string;
  SERVICE_VERSION: string;
}

export type AppEnv = {
  Bindings: Bindings;
};
